function Sparkline({bars=[],className='',color='#9dcf98'}:{bars?:any[];className?:string;color?:string}){if(bars.length<2)return <div className={className}/>;const values=bars.slice(-30).map(b=>b.close),min=Math.min(...values),span=Math.max(...values)-min||1,points=values.map((v,i)=>`${i/(values.length-1)*150},${34-(v-min)/span*28}`).join(' ');return <svg viewBox="0 0 150 40" preserveAspectRatio="none" className={className} role="img" aria-label="Recent closed prices"><polyline fill="none" stroke={color} strokeWidth="1.6" vectorEffect="non-scaling-stroke" points={points}/></svg>}
function Score({score,tier,large=false}:{score:any;tier?:string;large?:boolean}){const color=tier==='focus'?'#b7ee85':tier==='watch'?'#76d6da':'#9aaebc';return <div className={cn('flex items-center gap-2.5',large&&'gap-3')}><span className={cn('data-value font-mono text-sm',large&&'text-3xl tracking-[-2px]')} style={{color}}>{score??'—'}</span><Progress value={score??0} aria-label={`Attention ${score??'unrated'} out of 100`} className={cn('score-track h-1 w-12 bg-secondary',large&&'w-16')} style={{'--score-color':color} as any}/></div>}

function CandleChart({market,level,period}:{market:Market;level?:Level;period:number}){
 const [hover,setHover]=useState<number|null>(null),ref=useRef<SVGSVGElement>(null);const minutes=({'15m':15,'1h':60,'4h':240} as any)[market.interval??'1h']??60;
 const bars=(market.chart??[]).slice(-Math.ceil(period*60/minutes));if(!bars.length)return <div className="flex h-48 items-center justify-center text-xs text-muted-foreground">No candle data available.</div>;
 const w=450,h=220,l=5,r=65,t=12,b=26,pw=w-l-r,ph=h-t-b;let min=Math.min(...bars.map(b=>b.low)),max=Math.max(...bars.map(b=>b.high));if(level){min=Math.min(min,level.price);max=Math.max(max,level.price);}const pad=(max-min)*.12||max*.001;min-=pad;max+=pad;const y=(v:number)=>t+(max-v)/(max-min)*ph,x=(i:number)=>l+(i+.5)*pw/bars.length,bw=Math.max(.8,pw/bars.length*.57),active=hover===null?null:bars[hover];
 return <div><div className="mb-1 flex min-h-5 flex-wrap items-center gap-x-2 font-mono text-[9px] text-muted-foreground">{active?<><span>{paris(active.time,true)}</span><span>O {fmt(active.open)}</span><span>H {fmt(active.high)}</span><span>L {fmt(active.low)}</span><span>C {fmt(active.close)}</span></>:<><span className="inline-block h-px w-3 bg-cyan"/><span className="text-cyan">{level?.id??'Price context'} {level?fmt(level.price):''}</span><span className="ml-auto">HOVER TO INSPECT</span></>}</div><svg ref={ref} viewBox={`0 0 ${w} ${h}`} className="chart-cursor w-full" role="img" aria-label={`${market.base} closed candles and ${level?.id??'price context'}`} onPointerMove={e=>{const rect=ref.current!.getBoundingClientRect();setHover(Math.max(0,Math.min(bars.length-1,Math.floor(((e.clientX-rect.left)/rect.width*w-l)/pw*bars.length))));}} onPointerLeave={()=>setHover(null)}>
 {[0,1,2,3].map(k=><g key={k}><line x1={l} x2={w-r} y1={t+k*ph/3} y2={t+k*ph/3} stroke="#283646" strokeWidth=".6" strokeDasharray="2 5"/><text x={w-r+8} y={t+k*ph/3+3} className="chart-text">{fmt(max-k*(max-min)/3)}</text></g>)}
 {level&&<g><line x1={l} x2={w-r} y1={y(level.price)} y2={y(level.price)} stroke="#76d6da" strokeWidth=".8" strokeDasharray="5 4"/><rect x={w-r+2} y={y(level.price)-8} width={61} height={16} rx={3} fill="#1c3b44"/><text x={w-r+6} y={y(level.price)+3} className="chart-text" style={{fill:'#a1edf0',fontSize:8}}>{fmt(level.price)}</text></g>}
 {bars.map((bar,i)=><g key={bar.time} opacity={hover===null||i===hover?1:.55}><line x1={x(i)} x2={x(i)} y1={y(bar.high)} y2={y(bar.low)} stroke={bar.close>=bar.open?'#a6d87f':'#d68e87'} strokeWidth=".8"/><rect x={x(i)-bw/2} y={y(Math.max(bar.open,bar.close))} width={bw} height={Math.max(.8,Math.abs(y(bar.open)-y(bar.close)))} rx={.3} fill={bar.close>=bar.open?'#a6d87f':'#d68e87'}/></g>)}
 {hover!==null&&<line x1={x(hover)} x2={x(hover)} y1={t} y2={h-b} stroke="#b5c6d8" strokeWidth=".6" strokeDasharray="3 3"/>}<text x={l} y={h-5} className="chart-text">{paris(bars[0].time,true)}</text><text x={w-r} y={h-5} textAnchor="end" className="chart-text">{paris(bars.at(-1).time)} Paris</text></svg></div>;
}

function MarketDetail({market,interval,onPin,pinned,onMethod}:{market:Market;interval:string;onPin:()=>void;pinned:boolean;onMethod:()=>void}){
 const [period,setPeriod]=useState('72'),[levelId,setLevelId]=useState('');useEffect(()=>setLevelId(''),[market.base]);const nearest=[...market.attention.activeLevels].sort((a,b)=>a.distanceATR-b.distanceATR),level=nearest.find(l=>l.id===levelId)??market.attention.bestLevel??nearest[0],a=market.attention,signal=market.attention.details?.find((d:any)=>d.key==='signal')?.enabled?market.attention.bestSignal:null;
 return <Card className="gap-0 overflow-hidden border-border/80 bg-card py-0 shadow-none"><div className="flex items-center justify-between border-b border-border/70 px-5 py-3"><span className="heading-eyebrow">Market in focus</span><Structure value={market.structure}/></div><CardContent className="p-5"><div className="flex items-start justify-between"><div><div className="flex items-baseline gap-2"><h2 className="text-2xl font-semibold tracking-[-1px]">{market.base}</h2><span className="text-xs text-muted-foreground">/ USD</span></div><p className="mt-1 font-mono text-[9px] text-muted-foreground">BINANCE · {market.mapping.symbol}</p></div><Tip text={pinned?'Remove from watchlist':'Add to watchlist'}><Button variant="ghost" size="icon-sm" aria-label={`${pinned?'Unpin':'Pin'} ${market.base}`} onClick={onPin}><Star className={cn('size-4',pinned?'fill-mint text-mint':'text-muted-foreground')}/></Button></Tip></div><div className="mt-4 flex items-end justify-between"><div><div className="data-value text-[27px] font-medium tracking-[-1.25px]">{fmt(market.price)}</div><div className="mt-1 text-[10px] text-muted-foreground">Last closed price</div></div><Badge variant="outline" className="mb-1 border-border font-mono text-[9px] text-muted-foreground">{interval} candles</Badge></div>
 <div className="mt-6"><Tabs value={period} onValueChange={setPeriod}><div className="mb-3 flex items-center justify-between"><span className="heading-eyebrow">Price action</span><TabsList className="h-7 rounded-none bg-background p-.5">{[['24','24h'],['72','3d'],['120','5d']].map(([v,label])=><TabsTrigger key={v} value={v} className="h-6 px-2.5 text-[10px] data-[state=active]:bg-secondary data-[state=active]:text-foreground">{label}</TabsTrigger>)}</TabsList></div></Tabs><CandleChart market={{...market,interval}} level={level} period={+period}/></div>
 <div className="mt-4 rounded-none border border-mint/15 bg-mint/[.035] p-3.5"><div className="flex items-center justify-between"><div className="flex items-center gap-2"><Eye className="size-3.5 text-mint"/><span className="text-xs font-medium">Attention rating</span></div><Button variant="ghost" size="icon-xs" aria-label="Explain attention rating" onClick={onMethod}><Info className="size-3.5 text-muted-foreground"/></Button></div><div className="mt-2.5 flex items-end justify-between"><Score score={a.score} tier={a.tier} large/><span className="rounded-full border border-border/70 px-2 py-1 text-[9px] capitalize text-muted-foreground">{a.tier==='unrated'?'Unrated':a.tier}</span></div><p className="mt-2.5 text-[10px] leading-relaxed text-muted-foreground">{a.fresh?(a.reasons.join(' · ')||'No enabled rule contributed points.'):'Run a fresh scan to restore this rating.'}</p><ScoreBreakdown rating={a}/></div>
 <div className="mb-2 mt-6 flex items-center justify-between"><h3 className="heading-eyebrow">Enabled references</h3><span className="text-[9px] text-muted-foreground">Select to locate</span></div><div className="max-h-72 overflow-y-auto">{nearest.length===0&&<p className="py-3 text-xs text-muted-foreground">No enabled reference available.</p>}{nearest.map(l=><Button key={l.id} variant="ghost" onClick={()=>setLevelId(l.id)} className={cn('flex h-auto w-full justify-between rounded-none border-b border-border/65 px-0 py-3 text-left hover:bg-transparent',l.id===level?.id?'text-cyan':'text-foreground')}><span><span className="block text-[11px] font-medium">{l.id}</span><span className="mt-1 block font-mono text-[9px] font-normal text-muted-foreground">{l.price>market.price?'ABOVE':l.price<market.price?'BELOW':'AT'} CLOSE · {l?l.distanceATR.toFixed(2)+' ATR':'No level'}</span></span><span className="flex items-center gap-2 font-mono text-[11px] font-normal">{fmt(l.price)}<ArrowUpRight className="size-3 opacity-60"/></span></Button>)}</div>
 {level&&<details className="mt-4 border border-border p-3"><summary className="cursor-pointer text-xs text-cyan">About {level.id} · how to trade</summary><p className="mt-3 font-mono text-[9px] text-muted-foreground">Known since {paris((level as any).knownAt,true)} Paris</p><p className="mt-3 text-[10px] leading-6 text-muted-foreground">{levelCatalog.find(l=>l.id===level.id)?.calculation}</p><p className="mt-3 text-[10px] leading-6 text-muted-foreground">{levelCatalog.find(l=>l.id===level.id)?.trade}</p></details>}<div className="my-5 grid grid-cols-3 gap-2">{[['RSI 14',market.rsi14?.toFixed(1)??'—'],['EMA 50',fmt(market.ema50)],['EMA 200',fmt(market.ema200)]].map(([label,val])=><div key={label}><p className="font-mono text-[9px] text-muted-foreground">{label}</p><p className="mt-1.5 font-mono text-[11px]">{val}</p></div>)}</div><div className="rounded-none border border-border/70 bg-background/60 p-3.5"><div className="flex items-center gap-2"><Activity className={cn('size-3.5',signal?'text-cyan':'text-muted-foreground')}/><span className="text-[11px] font-medium">{signal?`${signal.direction} ${signal.family} confirmed`:'No recent confirmed entry'}</span></div><p className="mt-2 text-[10px] leading-5 text-muted-foreground">{signal?<>{paris(signal.confirmedAt,true)} Paris<br/>Close reference {fmt(signal.entryReference)} · Invalidation {fmt(signal.invalidation)}<br/>Independent signal; fill and occupancy unassessed.</>:<>Nearby levels are context. A strategy entry still requires a confirmed signal.</>}</p></div><p className="mt-4 flex items-center gap-1.5 text-[9px] text-muted-foreground"><Clock3 className="size-3"/>Candle close {paris(market.candleCloseAt,true)} Paris</p></CardContent></Card>;
}

